import React from 'react';

const skills = [
  { icon: '⚛️', name: 'React.js', level: 95 },
  { icon: '🟢', name: 'Node.js', level: 92 },
  { icon: '🚂', name: 'Express.js', level: 90 },
  { icon: '💙', name: 'Flutter', level: 85 },
  { icon: '🔥', name: 'Firebase', level: 88 },
  { icon: '⚡', name: 'Supabase', level: 82 },
  { icon: '🍃', name: 'MongoDB', level: 87 },
  { icon: '🐘', name: 'PostgreSQL', level: 85 },
  { icon: '🔌', name: 'REST APIs', level: 95 },
  { icon: '🐙', name: 'Git/GitHub', level: 93 },
  { icon: '🟨', name: 'JavaScript', level: 96 },
  { icon: '💎', name: 'TypeScript', level: 88 },
  { icon: '🎨', name: 'Tailwind CSS', level: 90 },
];

export default function Skills() {
  return (
    <section id="skills">
      <div className="section-inner">
        <div className="section-label">// 02 — skills</div>
        <h2 className="section-title">Tech <span>Stack</span></h2>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(140px, 1fr))', gap: '1rem' }}>
          {skills.map(skill => (
            <div key={skill.name}
              style={{
                background: 'var(--surface)',
                border: '1px solid var(--border)',
                borderRadius: 8, padding: '1.25rem 1rem',
                textAlign: 'center', transition: 'all 0.25s', cursor: 'default'
              }}
              onMouseEnter={e => {
                e.currentTarget.style.borderColor = 'var(--orange)';
                e.currentTarget.style.background = 'rgba(255,107,26,0.05)';
                e.currentTarget.style.transform = 'translateY(-3px)';
              }}
              onMouseLeave={e => {
                e.currentTarget.style.borderColor = 'var(--border)';
                e.currentTarget.style.background = 'var(--surface)';
                e.currentTarget.style.transform = 'none';
              }}>
              <div style={{ fontSize: '1.5rem', marginBottom: '0.5rem' }}>{skill.icon}</div>
              <div style={{ fontSize: '0.8rem', fontWeight: 700, color: 'var(--text)', marginBottom: '0.75rem' }}>{skill.name}</div>
              {/* Progress bar */}
              <div style={{ height: 3, background: 'rgba(255,255,255,0.06)', borderRadius: 2 }}>
                <div style={{
                  height: '100%', borderRadius: 2,
                  background: 'linear-gradient(90deg, var(--orange), #ff3c00)',
                  width: `${skill.level}%`,
                  transition: 'width 0.8s ease'
                }} />
              </div>
              <div style={{ fontSize: '0.65rem', color: 'var(--muted)', marginTop: 5, fontFamily: "'Space Mono', monospace" }}>
                {skill.level}%
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
